SELECT h.task_id AS taskId, h.task_type AS taskType, h.node_name AS taskName, h.instance_id AS instanceId, i.process_def_key AS processDefKey, d.process_name AS processDefName, h.operator_id AS assigneeId, h.operator_name AS assigneeName, h.create_time AS createTime, NULL AS dueDate, NULL AS priority, h.action AS status FROM wf_task_history h LEFT JOIN wf_process_instance i ON i.instance_id = h.instance_id LEFT JOIN wf_process_definition d ON d.process_def_key = i.process_def_key WHERE h.instance_id IN
#{instanceId}
ORDER BY h.create_time DESC
